public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (!decode) {
        // Decode the URI if necessary
        u = u.normalize().toASCIIString();
    }

    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    // Trim leading and trailing '/') if present
    path = path.replaceAll("^/+|/+$", "");

    int start = 0;

    while (start < path.length()) {
        int end = path.indexOf('/', start);
        if (end == -1) {
            end = path.length();
        }

        pathSegments.add(PathSegmentImpl.create(path.substring(start, end), decode));
        start = end + 1;
    }

    return pathSegments;
}
