public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    if (desiredCapacity == 0) {
        return 2; // 0 is prime
    }

    int i = (desiredCapacity + 1) * 3 / 4; // First prime number greater than floor((desiredCapacity + 1) * 3 / 4)

    // Check for prime numbers
    while (!isPrime(i)) {
        i++;
    }

    return i;
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }

    for (int j = 5; j * j <= num; j += 6) {
        if (num % j == 0 || num % (j + 2) == 0) {
            return false;
        }
    }

    return true;
}
