        } else {
            if (c == '\'') {
                escaping = false;
                // Escape single quote
                result.append("\\\'");
            } else if (c == '"') {
                escaping = false;
                // Escape double quote
                result.append("\\\"");
            } else if (c == '\n') {
                result.append("\\n");
            } else {
                result.append(c);
            }
        }
    }
    if (escaping) {
        // Handle unescaped quote or unescaped newline
        result.append("\\" + str.charAt(str.length() - 1));
    }
